+      if( ((u8)p1->zKey[i])>((u8)p2->zKey[i]) ){
+        /* p2 is smaller */
+        *ppOut = p2;
+        ppOut = &p2->pNext;
+        p2 = p2->pNext;
+      }else{
+        /* p1 is smaller */
+        *ppOut = p1;
+        ppOut = &p1->pNext;
+        p1 = p1->pNext;
+      }
+      *ppOut = 0;
+    }
+  }
+
+  return pRet;
+}
+
